@book{gorzhaltsan2023mezhdunarodnaya562421426,
 author = {Стрельцов, А. А. and Капустин, А. Я. and Полякова, Т. А. and Смирнов, А. А. and Касенова, М. Б. and Русинова, В. Р. and Шинкарецкая, Г. Г. and Жарова, А. К. and Пилюгин, П. Л. and Калицев, А. Е. and Горжалцан, В. А. and Герасимов, А. В. and Марков, А. С. and Милославская, Н. Г. and Мирошников, Б. Н. and Панин, А. В. and Коротков, С. В. and Бойко, К. С. and Волкова, С. В.},
