 numpages = {132},
 address = {НАМИБ Москва},
 annote = {В монографии представлены результаты исследования проблемы применения норм ответственного поведения государств в ИКТ-среде и даны научно обоснованные рекомендации по вопросам международного сотрудничества в области безопасного использования информационно-коммуникационных технологий (ИКТ) в формирующемся глобальном информационном обществе.Изыскания были направлены на содействие выработке новых принципов и норм международного права, регулирующих деятельность государств в глобальном информационном пространстве, в целях установления международно-правового режима обеспечения безопасности в сфере использования информационно-коммуникационных технологий.В монографии показано, что для практического применения норм ответственного поведения государств в ИКТ-среде необходимо решение проблем делимитации и демаркации зон ответственного поведения государств в ИКТ-среде, имплементации норм в национальное законодательство, а также развитие механизмов мирного разрешения споров, возникающих в связи с инцидентами в ИКТ-среде.Материалы монографии могут быть использованы представителями НАМИБ и заинтересованных федеральных органов государственной власти в процессе участия в деятельности РГОС и на других международных площадках по проблематике международной информационной безопасности.},
 language = {russian}
}

